-- -----------------------------------------------------
-- Table `SSO`.`user_course_progress`
-- -----------------------------------------------------
CREATE TABLE IF NOT EXISTS `SSO`.`user_course_progress` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `user_id` BIGINT NOT NULL,
  `course_id` BIGINT NOT NULL,
  `progress_percentage` DECIMAL(5,2) NOT NULL DEFAULT 0,
  `last_accessed_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `completed_at` DATETIME NULL,
  PRIMARY KEY (`id`),
  UNIQUE INDEX `user_course_UNIQUE` (`user_id` ASC, `course_id` ASC),
  INDEX `user_idx` (`user_id` ASC),
  INDEX `course_idx` (`course_id` ASC),
  CONSTRAINT `fk_progress_user`
    FOREIGN KEY (`user_id`)
    REFERENCES `SSO`.`user` (`id`)
    ON DELETE CASCADE
    ON UPDATE CASCADE,
  CONSTRAINT `fk_progress_course`
    FOREIGN KEY (`course_id`)
    REFERENCES `SSO`.`course` (`id`)
    ON DELETE CASCADE
    ON UPDATE CASCADE
) ENGINE = InnoDB;

